using SobhanNotificationHub.Models;namespace SobhanNotificationHub.Services;public sealed class DeviceRegistrationService(SobhanApiClient api,AuthTokenStore store){public async Task<DeviceCredentials> PairAsync(string code,string deviceName,CancellationToken ct){var result=await api.PairAsync(code,deviceName,ct);var credentials=new DeviceCredentials{DeviceUid=result.DeviceUid,DeviceToken=result.DeviceToken};store.Save(credentials);LoggingService.Info("device_paired",$"uid={result.DeviceUid}");return credentials;}public async Task DisconnectAsync(CancellationToken ct){try{await api.UnregisterAsync(ct);}finally{store.Clear();LoggingService.Info("device_disconnected");}}}
